<div class="mb-4 flex justify-end"><a class="btn btn-primary" href="<?=url('receivables/form')?>"><i data-lucide="plus"></i>Nova conta</a></div>
<form class="card mb-5 grid gap-3 p-4 sm:grid-cols-2 xl:grid-cols-7"><input type="hidden" name="route" value="receivables"><select class="field" name="status"><option value="">Status</option><?php foreach(['pendente'=>'Pendente','vencido'=>'Vencido','parcial'=>'Parcial','recebido'=>'Recebido'] as $v=>$l):?><option value="<?=$v?>" <?=($_GET['status']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><select class="field" name="category"><option value="">Categoria</option><?php foreach($categories as $o):?><option value="<?=$o['id']?>" <?=($_GET['category']??'')==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select><select class="field" name="contact"><option value="">Cliente</option><?php foreach($contacts as $o):?><option value="<?=$o['id']?>" <?=($_GET['contact']??'')==$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select><select class="field" name="payment_method"><option value="">Forma</option><?php foreach(['pix'=>'Pix','cartao_credito'=>'Cartão crédito','cartao_debito'=>'Cartão débito','boleto'=>'Boleto','dinheiro'=>'Dinheiro','transferencia'=>'Transferência'] as $v=>$l):?><option value="<?=$v?>" <?=($_GET['payment_method']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><input class="field" type="date" name="start" value="<?=e($_GET['start']??'')?>"><input class="field" type="date" name="end" value="<?=e($_GET['end']??'')?>"><button class="btn btn-light"><i data-lucide="list-filter"></i>Filtrar</button></form>
<div class="card table-wrap"><table class="data-table"><thead><tr><th>Situação</th><th>Descrição</th><th>Cliente</th><th>Categoria</th><th>Vencimento</th><th>Esperado</th><th>Recebido</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $i):$badge=status_badge($i['status'],$i['due_date']);?><tr><td><span class="rounded-full px-2 py-1 text-xs font-semibold <?=$badge[1]?>"><?=$badge[0]?></span></td><td class="font-medium"><?=e($i['description'])?></td><td><?=e($i['contact_name']?:'—')?></td><td><?=e($i['category_name']?:'—')?></td><td><?=br_date($i['due_date'])?></td><td class="font-semibold"><?=money($i['expected_amount'])?></td><td><?=money($i['received_amount'])?></td><td><div class="flex gap-1"><?php if($i['status']!=='recebido'):?><button type="button" class="receive-btn btn btn-primary !px-2 !py-1.5 text-xs" data-id="<?=$i['id']?>" data-value="<?=e((string)((float)$i['expected_amount']-(float)$i['received_amount']))?>">Confirmar</button><?php endif;?><a class="btn btn-light !p-1.5" href="<?=url('receivables/form')?>&id=<?=$i['id']?>"><i data-lucide="pencil"></i></a><form method="post" action="<?=url('receivables/delete')?>" data-confirm="Excluir esta conta?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$i['id']?>"><button class="btn btn-light !p-1.5 text-red-600"><i data-lucide="trash-2"></i></button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="8" class="text-center text-slate-500">Nenhuma conta encontrada.</td></tr><?php endif;?></tbody></table></div>
<dialog id="receiveDialog" class="w-[calc(100%-2rem)] max-w-md rounded-2xl bg-white p-0 text-slate-800 backdrop:bg-slate-950/60 dark:bg-slate-900 dark:text-white"><form method="post" action="<?=url('receivables/receive')?>" class="space-y-4 p-6"><?=csrf_field()?><input id="receiveId" type="hidden" name="id"><h2 class="text-lg font-semibold">Confirmar recebimento</h2><label><span class="label">Valor efetivamente recebido</span><input id="receiveValue" class="field" name="received_amount" inputmode="decimal" required></label><label><span class="label">Data do recebimento</span><input class="field" type="date" name="receipt_date" value="<?=date('Y-m-d')?>" required></label><div class="flex justify-end gap-2"><button type="button" class="btn btn-light" onclick="receiveDialog.close()">Cancelar</button><button class="btn btn-primary">Confirmar</button></div></form></dialog>
<?php $pageScripts='<script>document.querySelectorAll(".receive-btn").forEach(b=>b.addEventListener("click",()=>{receiveId.value=b.dataset.id;receiveValue.value=b.dataset.value;receiveDialog.showModal()}));</script>'; ?>
